local BroochMaker = {}
local PRODUCTS = {
    simple_bronze_brooch = { name = "Preprosta bronasta broška", bronzeCost = 1, ironCost = 1, time = 3, cost = 45, beauty = 22, prestige = 3, happiness = 1, description = "Preprosta bronasta broška za plašče." },
    silver_filigree_brooch = { name = "Srebrnofiligranska broška", silverCost = 1, bronzeCost = 1, ironCost = 1, time = 6, cost = 140, beauty = 38, prestige = 8, happiness = 2, description = "Srebrnofiligranska broška za trgovce." },
    gold_cameo_brooch = { name = "Zlati kameja broška", goldCost = 1, silverCost = 1, bronzeCost = 1, ironCost = 1, time = 9, cost = 340, beauty = 52, prestige = 16, happiness = 2, description = "Zlati kameja broška za plemiče." }
    , jewel_set_brooch = { name = "Draguljasta broška", goldCost = 1, silverCost = 1, bronzeCost = 1, ironCost = 1, jewelCost = 1, time = 13, cost = 800, beauty = 68, prestige = 28, happiness = 3, description = "Broška z draguljem za visoke plemiče." },
    pearl_accent_brooch = { name = "Bisernookrasna broška", goldCost = 2, silverCost = 1, bronzeCost = 1, ironCost = 1, jewelCost = 1, pearlCost = 1, time = 17, cost = 1800, beauty = 82, prestige = 42, happiness = 5, description = "Broška z bisernim okrasom za visoko plemstvo." },
    royal_grand_brooch = { name = "Kraljevski veliki broška", goldCost = 3, silverCost = 2, bronzeCost = 1, ironCost = 1, jewelCost = 2, pearlCost = 2, time = 24, cost = 4000, beauty = 95, prestige = 65, happiness = 12, description = "Velika kraljevska broška z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    brooch_workshop = { name = "Broškarska delavnica", cost = { gold = 240, wood = 100, stone = 120, bronze = 6, iron = 4 }, upkeep = 5, qualityBonus = 5 },
    filigree_loft = { name = "Filigranska podstrešje", cost = { gold = 900, wood = 240, stone = 240, silver = 6, gold = 4 }, upkeep = 21, qualityBonus = 18 },
    master_brooch_atelier = { name = "Mojstrski broškarski atelje", cost = { gold = 2600, wood = 360, stone = 480, silver = 30, gold = 6 }, upkeep = 60, qualityBonus = 30 },
    royal_brooch_palace = { name = "Kraljevska broškarska palača", cost = { gold = 11000, wood = 580, stone = 760, gold = 70, jewel = 18 }, upkeep = 220, qualityBonus = 55, prestigeBonus = 50 },
}
BroochMaker.bronzeStock = 12; BroochMaker.ironStock = 10; BroochMaker.silverStock = 8; BroochMaker.goldStock = 6; BroochMaker.jewelStock = 4; BroochMaker.pearlStock = 4
BroochMaker.productStock = {}; BroochMaker.buildings = {}; BroochMaker.maker = nil; BroochMaker.activeMaking = {}; BroochMaker.totalProducts = 0; BroochMaker.dayTimer = 0
function BroochMaker.init() BroochMaker.bronzeStock=12; BroochMaker.ironStock=10; BroochMaker.silverStock=8; BroochMaker.goldStock=6; BroochMaker.jewelStock=4; BroochMaker.pearlStock=4; BroochMaker.productStock={}; BroochMaker.buildings={}; BroochMaker.maker=nil; BroochMaker.activeMaking={}; BroochMaker.totalProducts=0; BroochMaker.dayTimer=0; print("[BroochMaker] Royal Brooch Maker System initialized (6 products, 4 buildings)") end
function BroochMaker.hireMaker(n,s) s=s or math.random(55,90); local c=540+s*11; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; BroochMaker.maker={name=n or ("Broškar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Broškar najet: %s (spretnost: %d)",BroochMaker.maker.name,s),"success") end; return true end
function BroochMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function BroochMaker.build(id) local ok,e=BroochMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(BroochMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function BroochMaker.getQualityBonus() local b=0; for _,bd in ipairs(BroochMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function BroochMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.bronzeCost and BroochMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.ironCost and BroochMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.silverCost and BroochMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and BroochMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and BroochMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and BroochMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #BroochMaker.buildings==0 then return false,"Potrebna broškarska delavnica" end; if not BroochMaker.maker then return false,"Potreben broškar" end; return true end
function BroochMaker.make(pt,qty) qty=qty or 1; local ok,e=BroochMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.bronzeCost then BroochMaker.bronzeStock=BroochMaker.bronzeStock-d.bronzeCost*qty end; if d.ironCost then BroochMaker.ironStock=BroochMaker.ironStock-d.ironCost*qty end; if d.silverCost then BroochMaker.silverStock=BroochMaker.silverStock-d.silverCost*qty end; if d.goldCost then BroochMaker.goldStock=BroochMaker.goldStock-d.goldCost*qty end; if d.jewelCost then BroochMaker.jewelStock=BroochMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then BroochMaker.pearlStock=BroochMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if BroochMaker.maker then t=math.max(1,t-math.floor(BroochMaker.maker.skill/13)) end; table.insert(BroochMaker.activeMaking,{id="brooch_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,beauty=d.beauty or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function BroochMaker.completeMaking(m) local q=1.0+(BroochMaker.getQualityBonus()/100); if BroochMaker.maker then q=q+(BroochMaker.maker.skill/140) end; q=math.min(2.5,q); BroochMaker.productStock[m.productType]=(BroochMaker.productStock[m.productType] or 0)+m.quantity; BroochMaker.totalProducts=BroochMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if BroochMaker.maker then BroochMaker.maker.itemsMade=BroochMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then BroochMaker.maker.skill=math.min(100,BroochMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Broška izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"brooch.completed",{productName=m.productName,beauty=m.beauty,prestige=m.prestige,happiness=m.happiness}) end end
function BroochMaker.update(dt) if not _G.state then return end; BroochMaker.dayTimer=BroochMaker.dayTimer+dt; if BroochMaker.dayTimer>=30 then BroochMaker.dayTimer=0; for i=#BroochMaker.activeMaking,1,-1 do local m=BroochMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then BroochMaker.completeMaking(m); table.remove(BroochMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(BroochMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if BroochMaker.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function BroochMaker.getStats() return {bronzeStock=BroochMaker.bronzeStock,ironStock=BroochMaker.ironStock,silverStock=BroochMaker.silverStock,goldStock=BroochMaker.goldStock,jewelStock=BroochMaker.jewelStock,pearlStock=BroochMaker.pearlStock,productStock=BroochMaker.productStock,numBuildings=#BroochMaker.buildings,hasMaker=BroochMaker.maker~=nil,makerName=BroochMaker.maker and BroochMaker.maker.name or "—",makerSkill=BroochMaker.maker and BroochMaker.maker.skill or 0,activeMaking=#BroochMaker.activeMaking,totalProducts=BroochMaker.totalProducts} end
return BroochMaker
